const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [n, t] = line.split(' ').map(Number);

    // dp[i][y][h][v][p] = number of ways for prefix of length i
    // ending with value y (1..4), having h humps, v valleys,
    // and previous value p (1..4) for i >= 2.
    // For i=1, we don't have previous value.

    // Initialize for i=1
    let dp = Array(5).fill(0).map(() => 
        Array(t + 1).fill(0).map(() => 
            Array(t).fill(0).map(() => 
                Array(5).fill(0)
            )
        )
    );

    for (let y = 1; y <= 4; y++) {
        // For i=1, we store in dp[y][0][0][0] (using p=0 as dummy for no previous)
        // But we need to handle transition to i=2 specially.
        // Let's use a different structure for i=1.
    }

    // Better: dp[i][y][h][v][p] where i is implicit in the loop.
    // For i=1:
    let prev = Array(5).fill(0).map(() => 
        Array(t + 1).fill(0).map(() => 
            Array(t).fill(0).map(() => 
                Array(5).fill(0)
            )
        )
    );

    for (let y = 1; y <= 4; y++) {
        prev[y][0][0][0] = 1; // p=0 means no previous
    }

    for (let i = 2; i <= n; i++) {
        let curr = Array(5).fill(0).map(() => 
            Array(t + 1).fill(0).map(() => 
                Array(t).fill(0).map(() => 
                    Array(5).fill(0)
                )
            )
        );

        for (let y = 1; y <= 4; y++) { // current y
            for (let p = 1; p <= 4; p++) { // previous y (p != y)
                if (p === y) continue;
                for (let h = 0; h <= t; h++) {
                    for (let v = 0; v <= t - 1; v++) {
                        // sum over pprev (previous previous)
                        if (i === 2) {
                            // pprev is dummy (0), no hump/valley check
                            if (prev[p][h][v][0] > 0) {
                                curr[y][h][v][p] += prev[p][h][v][0];
                            }
                        } else {
                            for (let pprev = 1; pprev <= 4; pprev++) {
                                if (pprev === p) continue; // should not happen in valid states
                                let nh = h;
                                let nv = v;
                                // check if p is hump or valley
                                if (pprev < p && p > y) nh++;
                                else if (pprev > p && p < y) nv++;
                                if (nh <= t && nv <= t - 1) {
                                    curr[y][nh][nv][p] += prev[p][h][v][pprev];
                                }
                            }
                        }
                    }
                }
            }
        }
        prev = curr;
    }

    let ans = 0;
    for (let y = 1; y <= 4; y++) {
        for (let p = 1; p <= 4; p++) {
            ans += prev[y][t][t-1][p];
        }
    }

    console.log(ans);

    rl.close();
});
